meta.script:
(function () {
	try {
		var d = document.documentElement;
		var NL_CHOICES = ['daily', 'weekly', 'none'];
		var authed = new RegExp('(?:^|;\\s*)hwh_auth=').test(document.cookie);
		// Native WordPress user: reveal the authenticated UI pre-paint, but leave the
		// hydration below to the flag-cookie population — their display and
		// newsletter state is localized server-side, so the state fetch would be pure
		// overhead.
		if (false) d.classList.add('hwh-authed');
		if (authed) {
			d.classList.add('hwh-authed');
			// Own try/catch: a corrupt newsletter payload must not stop the avatar
			// initials below from painting.
			try {
				var nlRaw = window.sessionStorage && sessionStorage.getItem('hwh_newsletter');
				var nlChoice = nlRaw ? (JSON.parse(nlRaw) || {}).choice : '';
				if (NL_CHOICES.indexOf(nlChoice) > -1) {
					d.classList.add('hwh-nl-' + nlChoice);
				}
			} catch (e2) {}
		}
		var raw = window.sessionStorage && sessionStorage.getItem('hwh_display');
		if (raw) {
			var p = JSON.parse(raw);
			if (p && p.initials) {
				d.style.setProperty('--hwh-initials', JSON.stringify(p.initials));
			}
			window.__hwhDisplay = p;
		} else if (authed) {
			// No cached display yet (first page of the tab): start the state fetch
			// now so the avatar initials paint without waiting for the deferred JS.
			window.__hwhStatePromise = fetch('https://www.blogdumoderateur.com/core/wp-admin/admin-ajax.php', {
				method: 'POST',
				credentials: 'same-origin',
				headers: { 'Content-Type': 'application/x-www-form-urlencoded; charset=UTF-8' },
				body: 'action=hwh_get_user_state&nonce=c9f264d872'
			}).then(function (r) { return r.json(); }).then(function (res) {
				if (res && res.success && res.data && res.data.display && res.data.display.initials) {
					d.style.setProperty('--hwh-initials', JSON.stringify(res.data.display.initials));
				}
				// Narrows the newsletter-state flash to this round-trip on the first
				// page of the tab; later pages read it from sessionStorage pre-paint.
				if (res && res.success && res.data && res.data.newsletter
					&& NL_CHOICES.indexOf(res.data.newsletter.choice) > -1) {
					d.classList.add('hwh-nl-' + res.data.newsletter.choice);
				}
				return res;
			}).catch(function () { return null; });
		}
	} catch (e) {}
})();

link.script:
(function (i, s, o, g, r, a, m) {
i["abtiming"] = 1 * new Date();
a = s.createElement(o),
m = s.getElementsByTagName(o)[0]; a.async = 1; a.src = g; m.parentNode.insertBefore(a, m)
})(window, document, "script", "//try.abtasty.com/5e8712ab98af61ffeca4088008680b5a.js");

// Correction compatible cache : on relit l'état de connexion depuis le
// cookie hwh_auth avant le chargement de GTM, sinon tout visiteur servi
// par la page mutualisée serait compté comme déconnecté.
try {
	if ( /(?:^|;\s*)hwh_auth=/.test( document.cookie ) && window.dataLayer && window.dataLayer[0] ) {
		window.dataLayer[0].user_logged_in = true;
	}
} catch ( e ) {}
